from core import *
text='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Phase2C · Physical-device report</title><style>body{font:17px system-ui;max-width:850px;margin:24px auto;padding:16px;background:#172333;color:#eee}input,select,textarea,button{font:inherit;padding:10px;box-sizing:border-box;max-width:100%}label{display:block;margin:16px 0}textarea{width:100%}a{color:#9ee}button{min-height:44px}#result{white-space:pre-wrap}</style><h1>Physical-device review · Phase2C</h1><p>Default status: NOT TESTED. Fill this form on the actual Android Chrome or iPhone Safari device after running the local review package. A desktop viewport is not physical-device evidence. Reports download locally; nothing is sent to a server.</p><p><a href="../../index.html">Open actual Phaser</a> · <a href="REVIEW.html">Review gallery</a></p><form id="report"><label>Device model <input name="model" required></label><label>OS / version <input name="os" required></label><label>Browser / version <input name="browser" required></label><label>Reviewer <input name="reviewer" required></label><label>Checkpoint / ZIP SHA256 <input name="checkpoint" required></label><label>Recorded evidence filenames or links <textarea name="evidence" rows="3" placeholder="Actual screen recording, screenshots and any trace"></textarea></label><div id="checks"></div><label>Observations, timing, temperature, crashes and visual defects <textarea name="notes" rows="5"></textarea></label><button type="submit">Export local JSON test report</button></form><pre id="result"></pre><script>
const checks=['Landscape safe areas and44px controls','All12 gallery and category scrolling','Default/customized front,right,back walk and run','Glasses,hat,hair and garment occlusion','Save,rename,delete,apply,cancel and reload presets','World position,visited markers and progress retained','Joystick isolation and return to gameplay','60character switches and100cosmetic preview/apply','Resource counts,visible smoothness and thermal behavior'];const root=document.querySelector('#checks');checks.forEach((label,i)=>{const l=document.createElement('label');l.textContent=label+' ';const s=document.createElement('select');s.name='check'+i;['NOT TESTED','PASS','FAIL','WARN'].forEach(v=>{const o=document.createElement('option');o.value=v;o.textContent=v;s.append(o)});l.append(s);root.append(l)});document.querySelector('form').onsubmit=e=>{e.preventDefault();const q=Object.fromEntries(new FormData(e.target));if(checks.some((_,i)=>q['check'+i]==='PASS')&&!q.evidence.trim()){document.querySelector('#result').textContent='Recorded actual-device evidence is required before reporting PASS.';return}const rows=checks.map((name,i)=>({name,status:q['check'+i]}));Object.keys(q).filter(k=>k.startsWith('check')&&k!=='checkpoint').forEach(k=>delete q[k]);const report={schemaVersion:1,phase:'2C',timestamp:new Date().toISOString(),...q,userAgent:navigator.userAgent,viewport:[innerWidth,innerHeight],dpr:devicePixelRatio,checks:rows,attestation:'Human-entered actual-device observations. Not an automated certification.'};const data=JSON.stringify(report,null,2);document.querySelector('#result').textContent=data;const u=URL.createObjectURL(new Blob([data],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='phase2c-device-report-'+Date.now()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
</script>'''
